<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { post } from '@/api/client'
import { useAugmentStore } from '@/stores/augment'
const store=useAugmentStore(),busy=ref(false),error=ref(''),preview=ref<{uri:string;before:string;after:string;note:string}>(),shownKey=ref('')
const key=computed(()=>JSON.stringify([store.scope,store.recipe,store.exampleUri]))
let generation=0
watch(key,()=>{generation++;preview.value=undefined;busy.value=false;error.value=''})
async function load(){const n=++generation;const requested=key.value;busy.value=true;error.value='';try{const result=await post<NonNullable<typeof preview.value>>('/augment/preview',{uris:store.scope,recipe:store.recipe,uri:store.exampleUri});if(n===generation){preview.value=result;shownKey.value=requested}}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation)busy.value=false}}
function next(dir:number){const i=Math.max(0,store.scope.indexOf(store.exampleUri));store.setExample(store.scope[Math.max(0,Math.min(store.scope.length-1,i+dir))]||'')}
</script>
<template><section class="apreview" aria-label="增强效果预览"><header><h2>看看增强后的实际变化</h2><button :disabled="busy||!store.hasRecipe||!store.scope.length||store.running" @click="load">{{busy?'正在生成样例…':'预览这一张的效果'}}</button></header><p>这里只预览一张图片的第一份副本，不写入原图或新版本。改动配方后请重新预览。</p><div class="example-picker"><button :disabled="store.running||!store.scope.length" @click="next(-1)">上一张示例</button><span :title="store.exampleUri">{{store.exampleUri.split(/[\\/]/).pop()||'尚未选择图片'}}</span><button :disabled="store.running||!store.scope.length" @click="next(1)">下一张示例</button></div><p v-if="error" class="failure" role="alert">预览失败：{{error}} <button @click="load">重试</button></p><div v-if="preview&&shownKey===key" class="pair"><figure><figcaption>原始图片</figcaption><img :src="'data:image/png;base64,'+preview.before" alt="增强前原图"/></figure><figure><figcaption>当前配方的实际样例</figcaption><img :src="'data:image/png;base64,'+preview.after" alt="实际增强效果"/></figure></div><div v-else class="empty">{{busy?'正在按当前随机编号和配方处理…':'选好左侧配方后，点击预览查看前后对照。'}}</div><p v-if="preview">{{preview.note}}</p><div v-if="store.warnings.length" class="warnings" role="alert"><b>生成前请确认</b><p v-for="warning in store.warnings" :key="warning">{{warning}}</p></div></section></template>
<style scoped>
.apreview{flex:1;min-width:0;overflow:auto;padding:22px}.apreview header{display:flex;align-items:center;justify-content:space-between;gap:15px;flex-wrap:wrap}.apreview h2{margin:0;font-size:16px}.apreview p{font-size:11px;color:var(--text-secondary);line-height:1.8}.apreview button{background:var(--bg-panel);color:var(--text-primary);border:1px solid var(--border);border-radius:5px;padding:8px 12px;cursor:pointer}.apreview button:disabled{opacity:.4;cursor:default}.example-picker{display:flex;align-items:center;gap:10px;margin:18px 0}.example-picker span{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:11px}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.pair figure{margin:0;border:1px solid var(--border);border-radius:6px;overflow:hidden;background:var(--bg-panel)}figcaption{padding:10px;font-size:11px;color:var(--text-secondary)}.pair img{display:block;width:100%;object-fit:contain;background:#03090e}.empty{border:1px dashed var(--border);padding:100px 20px;text-align:center;border-radius:7px;color:var(--text-muted);font-size:12px}.failure{color:var(--danger)!important}.warnings{padding:15px;background:var(--bg-panel);border:1px solid var(--warning);margin-top:20px;border-radius:6px}.warnings b{font-size:12px;color:var(--warning)}@media(max-width:700px){.pair{grid-template-columns:1fr}}
</style>
